// Package periph is a database of microcontroller device profiles: the
// architecture, memory map and load address of a part, its interrupt vectors
// and the names of its peripheral registers, bit fields and enumerated field
// values. The data is a compressed digest of vendor CMSIS-SVD (ARM, RISC-V,
// Xtensa) and Microchip ATDF (AVR) files, generated by ./gen and embedded
// from ./data; each device is decompressed lazily by Load.
package periph

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// DeviceInfo is the cheap description of a device available without loading it.
type DeviceInfo struct {
	Name        string // "STM32F103xx", "ATmega328P", "ESP32"
	Vendor      string
	Family      string // "STM32F1", "AVR", "ESP32"...
	Arch        string // the disassembler ID: "arm", "avr", "xtensa", "riscv32"
	Core        string // "Cortex-M3", "AVR8", "Xtensa LX6"...
	Description string
	Patterns    []string // part-number prefixes covered ('?' matches any character)
	Source      string   // the source file the data was generated from
}

// Device is a loaded device profile.
type Device struct {
	Name        string
	Vendor      string
	Family      string
	Arch        string
	Core        string
	Description string
	// Part is the part number Load was called with when it was resolved
	// through a part-number pattern (e.g. "STM32F103C8"); Memory then has the
	// Flash/RAM sizes of that part where they are known.
	Part        string
	Memory      []Region // Flash, SRAM, peripherals, ... sorted by space and address
	LoadAddr    uint64   // where a firmware binary starts (0x08000000 for STM32)
	Interrupts  []Interrupt
	Peripherals []Peripheral

	regs   []*Register // sorted by address
	maxEnd []uint64    // maxEnd[i] = max(regs[0..i].end)
}

// Region is a memory region. Kind is one of "flash", "ram", "rom",
// "periph", "eeprom", "fuses" (and for AVR also "regs", "lockbits",
// "signatures", "user_signatures", "osccal", "other"). Space is empty for a
// unified address space; AVR regions name their address space ("prog",
// "data", "eeprom", "fuses", ...).
type Region struct {
	Name  string
	Start uint64
	Size  uint64
	Kind  string
	Space string
}

// End returns the first address after the region.
func (r Region) End() uint64 { return r.Start + r.Size }

// Interrupt is an interrupt vector. For ARM Cortex-M Number is the CMSIS
// IRQn (system exceptions are negative: Reset = -15 ... SysTick = -1; the
// vector table slot is Number+16); for AVR it is the vector number (RESET = 0,
// INT0 = 1 on ATmega328P); for ESP32 it is the interrupt-matrix source number.
type Interrupt struct {
	Number      int
	Name        string
	Description string
}

// Peripheral is a peripheral instance.
type Peripheral struct {
	Name        string
	Description string
	Group       string
	Base        uint64
	Size        uint64
}

// Register is a memory-mapped register at an absolute address. For AVR the
// address is the data-space address (I/O address + 0x20 for classic AVR).
type Register struct {
	Peripheral  string
	Name        string
	Description string
	Addr        uint64
	Size        int // bits
	Reset       uint64
	Fields      []Field
	style       byte // label style: 0 "P->R", 1 "R", 2 "P.R"
}

// Field is a bit field of a register: bits [Bit, Bit+Bits). Mask is non-zero
// only for a non-contiguous field (some AVR fields, e.g. WDP in WDTCSR); the
// field value is then the masked bits packed together.
type Field struct {
	Name        string
	Description string
	Bit         int
	Bits        int
	Mask        uint64
	Values      []EnumValue
}

// EnumValue is a named value of a field.
type EnumValue struct {
	Name        string
	Description string
	Value       uint64
}

// FieldValue is a decoded field.
type FieldValue struct {
	Field *Field
	Value uint64
	Text  string // "PLLON=1 (PLL on)"
}

// End returns the first address after the register.
func (r *Register) End() uint64 {
	n := uint64(r.Size / 8)
	if n == 0 {
		n = 1
	}
	return r.Addr + n
}

// Label returns the conventional C name: "RCC->APB2ENR" (CMSIS),
// "PORTB" (classic AVR), "PORTA.OUT" (AVR8X).
func (r *Register) Label() string {
	switch {
	case r.Peripheral == "" || r.style == 1:
		return r.Name
	case r.style == 2:
		return r.Peripheral + "." + r.Name
	}
	return r.Peripheral + "->" + r.Name
}

// FieldMask returns the bit mask of the field within the register.
func (f *Field) FieldMask() uint64 {
	if f.Mask != 0 {
		return f.Mask
	}
	if f.Bits >= 64 {
		return ^uint64(0) << uint(f.Bit)
	}
	return ((uint64(1) << uint(f.Bits)) - 1) << uint(f.Bit)
}

// Extract returns the value of the field in a register value.
func (f *Field) Extract(v uint64) uint64 {
	if f.Mask == 0 {
		return (v & f.FieldMask()) >> uint(f.Bit)
	}
	var out uint64
	k := 0
	for b := 0; b < 64; b++ {
		if f.Mask&(1<<uint(b)) != 0 {
			if v&(1<<uint(b)) != 0 {
				out |= 1 << uint(k)
			}
			k++
		}
	}
	return out
}

// Enum returns the named value of the field equal to v.
func (f *Field) Enum(v uint64) (*EnumValue, bool) {
	for i := range f.Values {
		if f.Values[i].Value == v {
			return &f.Values[i], true
		}
	}
	return nil, false
}

// Decode splits a register value into its fields.
func (r *Register) Decode(value uint64) []FieldValue {
	out := make([]FieldValue, 0, len(r.Fields))
	for i := range r.Fields {
		f := &r.Fields[i]
		v := f.Extract(value)
		out = append(out, FieldValue{Field: f, Value: v, Text: fieldText(f, v)})
	}
	return out
}

func fieldText(f *Field, v uint64) string {
	var b strings.Builder
	b.WriteString(f.Name)
	b.WriteByte('=')
	if v < 10 {
		b.WriteString(strconv.FormatUint(v, 10))
	} else {
		b.WriteString("0x" + strings.ToUpper(strconv.FormatUint(v, 16)))
	}
	if e, ok := f.Enum(v); ok {
		t := e.Description
		if t == "" {
			t = e.Name
		}
		b.WriteString(" (" + t + ")")
	}
	return b.String()
}

// DecodeString formats the decoded fields: "PLLON=1 (PLL on), HSEON=0".
// Zero-valued single-bit fields without a named value are omitted when
// skipZero is set.
func (r *Register) DecodeString(value uint64, skipZero bool) string {
	var parts []string
	for _, fv := range r.Decode(value) {
		if skipZero && fv.Value == 0 && fv.Field.Bits == 1 && len(fv.Field.Values) == 0 {
			continue
		}
		parts = append(parts, fv.Text)
	}
	return strings.Join(parts, ", ")
}

// Registers returns all registers sorted by address.
func (d *Device) Registers() []*Register { return d.regs }

// RegisterAt returns the register containing addr (the lowest-addressed one
// if registers overlap, e.g. alternate views).
func (d *Device) RegisterAt(addr uint64) (*Register, bool) {
	regs := d.regs
	// first register with Addr > addr
	lo, hi := 0, len(regs)
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		if regs[m].Addr <= addr {
			lo = m + 1
		} else {
			hi = m
		}
	}
	var found *Register
	for j := lo - 1; j >= 0 && d.maxEnd[j] > addr; j-- {
		if regs[j].End() > addr {
			found = regs[j]
		}
	}
	return found, found != nil
}

// RegisterByName finds a register by its label ("RCC->APB2ENR", "PORTB",
// "PORTA.OUT") or by "PERIPH.NAME" / plain name (case-insensitive).
func (d *Device) RegisterByName(name string) (*Register, bool) {
	var plain *Register
	for _, r := range d.regs {
		if strings.EqualFold(r.Label(), name) || strings.EqualFold(r.Peripheral+"."+r.Name, name) || strings.EqualFold(r.Peripheral+"->"+r.Name, name) {
			return r, true
		}
		if plain == nil && strings.EqualFold(r.Name, name) {
			plain = r
		}
	}
	return plain, plain != nil
}

// PeripheralAt returns the peripheral instance whose address block contains addr.
func (d *Device) PeripheralAt(addr uint64) (*Peripheral, bool) {
	for i := range d.Peripherals {
		p := &d.Peripherals[i]
		if p.Size > 0 && addr >= p.Base && addr-p.Base < p.Size {
			return p, true
		}
	}
	return nil, false
}

// RegionAt returns the memory region containing addr (in the unified space,
// or the AVR "data" space).
func (d *Device) RegionAt(addr uint64) (*Region, bool) {
	var best *Region
	for i := range d.Memory {
		m := &d.Memory[i]
		if m.Space != "" && m.Space != "data" {
			continue
		}
		if addr >= m.Start && addr-m.Start < m.Size && (best == nil || m.Size < best.Size) {
			best = m
		}
	}
	return best, best != nil
}

// Interrupt returns the interrupt with the given number.
func (d *Device) Interrupt(n int) (*Interrupt, bool) {
	i := sort.Search(len(d.Interrupts), func(i int) bool { return d.Interrupts[i].Number >= n })
	if i < len(d.Interrupts) && d.Interrupts[i].Number == n {
		return &d.Interrupts[i], true
	}
	return nil, false
}

// Vector returns the handler of a vector-table slot: for Cortex-M the slot
// is IRQn+16 (slot 0 is the initial stack pointer and has no handler); for
// other architectures it is the interrupt number.
func (d *Device) Vector(slot int) (*Interrupt, bool) {
	if d.Arch == "arm" && strings.HasPrefix(d.Core, "Cortex-M") {
		if slot <= 0 {
			return nil, false
		}
		return d.Interrupt(slot - 16)
	}
	return d.Interrupt(slot)
}

// Region returns the first region of the given kind ("flash", "ram", ...).
func (d *Device) Region(kind string) (*Region, bool) {
	for i := range d.Memory {
		if d.Memory[i].Kind == kind {
			return &d.Memory[i], true
		}
	}
	return nil, false
}

func (d *Device) String() string {
	if d.Part != "" {
		return fmt.Sprintf("%s (%s)", d.Part, d.Name)
	}
	return d.Name
}

// cortexExceptions are the Cortex-M system exceptions (CMSIS IRQn numbers).
func cortexExceptions(core string) []Interrupt {
	// ARMv6-M / ARMv8-M Baseline have no configurable faults or debug monitor
	v6m := strings.HasPrefix(core, "Cortex-M0") || core == "Cortex-M1" || core == "Cortex-M23"
	out := []Interrupt{
		{-15, "Reset", "Reset handler"},
		{-14, "NonMaskableInt", "Non-maskable interrupt"},
		{-13, "HardFault", "Hard fault"},
	}
	if !v6m {
		out = append(out,
			Interrupt{-12, "MemoryManagement", "Memory management fault"},
			Interrupt{-11, "BusFault", "Bus fault"},
			Interrupt{-10, "UsageFault", "Usage fault"})
		if core == "Cortex-M33" || core == "Cortex-M55" || core == "Cortex-M35P" {
			out = append(out, Interrupt{-9, "SecureFault", "Secure fault"})
		}
	}
	out = append(out, Interrupt{-5, "SVCall", "Supervisor call (SVC)"})
	if !v6m {
		out = append(out, Interrupt{-4, "DebugMonitor", "Debug monitor"})
	}
	out = append(out,
		Interrupt{-2, "PendSV", "Pendable service request"},
		Interrupt{-1, "SysTick", "System tick timer"})
	return out
}
